package main

import (
	"fmt"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"

	"github.com/avatica-protocol/avro-go-gen/schema"
)

func readAndParseGoFile(filename string) (*schema.Schema, error) {
	fileBytes, err := ioutil.ReadFile(filename)
	if err != nil {
		return nil, fmt.Errorf("failed to read file: %w", err)
	}

	parsed, err := parser.ParseSource(string(fileBytes), token.NewFileSet())
	if err != nil {
		return nil, fmt.Errorf("failed to parse source code: %w", err)
	}
	astNode := parsed.(*ast.File)

	schemaBuilder := &schema.Builder{
		TypeRegistry: schema.TypeRegistry{},
	}

	for _, decl := range astNode.Decls {
		switch d := decl.(type) {
		case *ast.GenDecl:
			if d.Tok == token.TYPE || d.Tok == token.CONST {
				if !d.Specs.IsValid() {
					continue // Skip if no specs are provided
				}
				for _, spec := range d.Specs.List {
					if t, ok := spec.(*ast.TypeSpec); ok {
						// Parse struct type
						if len(t.Name.Elems) > 0 {
							for _, elem := range t.Name.Elems {
								if e, ok := elem.(*ast.Ident); ok && e.Name == "StructName" { // Replace with your actual struct name
									structName := e.Name
									break
								}
							}
							if len(structName) > 0 {
								schemaBuilder.AddType(&schema.StructType{Name: structName})
							} else {
								log.Printf("No struct found with name 'StructName' in file '%s'", filename)
							}
						}
					}
				}
			}
		}
	}

	if schemaBuilder.Types.Len() == 0 {
		log.Fatalf("Failed to find any StructTypes")
	}

	return schemaBuilder.BuildSchema(), nil
}

func main() {
	filename := "your_go_file.go"
	outputFileName := "struct.avsc"

	// Generate Avro Schema
	schema, err := readAndParseGoFile(filename)
	if err != nil {
		log.Fatalf("Error reading or parsing file: %v\n", err)
	}

	// Write generated schema to file
	err = ioutil.WriteFile(outputFileName, []byte(schema.String()), 0644)
	if err != nil {
		log.Fatalf("Error writing schema to file: %v\n", err)
	}

	fmt.Println(fmt.Sprintf("Generated schema saved as %s", outputFileName))
}
```

### Explanation:

1. **Reading the File**: The program reads the contents of the specified Go source file.
2. **Parsing the Source Code**: Using the `parser` package, we parse the source code into an AST (Abstract Syntax Tree).
3. **Analyzing Types**: We then traverse through the AST to identify and extract all the defined types (structs). This includes checking each declaration (`*ast.GenDecl`) to see if it's a type definition using `token.TYPE`.
4. **Building the Schema**: Once we've identified all the structs, we create a new `schema.Builder` instance and add these structs to it. Finally, we build the schema using this builder.
5. **Writing the Schema**: After building the schema, we write it to a file named `struct.avsc`.

